"""Refresh a truthful Chinese HTML experiment report from saved evidence."""
import argparse,html,json,time,re
from pathlib import Path
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);a=ap.parse_args();r=a.root
    review=json.loads((r/'CONTINUATION_REVIEW_20261001.json').read_text(encoding='utf-8'));state=json.loads((r/'EXECUTION_STATE_20261001.json').read_text(encoding='utf-8'));geom=json.loads((r/'GEOMETRY_PROXY_AUDIT_SUMMARY_20261001.json').read_text(encoding='utf-8'));observer=json.loads((r/'SAM3_DIAGNOSTICS_SUMMARY_20261001.json').read_text(encoding='utf-8'))
    rows=[]
    brief={35:'用源图可见表面优化抬升姿态；仍存在侧面光照条带与缺口材质问题。',36:'源图关键点配准后改善位置一致性；新切面和继承侧面仍需改进。',37:'同一椭球切割体定义缺口与勺上部分；模型原始输出和几何合成分开保存。',38:'原图亮度梯度校正对照，尚不足以获得自然表面。',39:'限制材质频率的对照；下边缘跨光栅材质错误尚未修复。',40:'修复 CPU 食物标签和 GPU 金属颜色混用。保留光照与缺口的完整对照。',41:'两个噪声强度、全部种子已检查；低噪声多保留原有刚性表面先验。',42:'纯噪声材质生成已检查；直接替换颜色可能增加原图没有的配料。',43:'焦距与源图关键点扰动诊断；拟合不稳定，未用于改变当前动作几何。',44:'只投影光照及微纹理统计；二值材质遮罩会留下边界和色块。',45:'扩大材质边界的对照；仍存在不规则表面区域。',46:'连续源图颜色置信度与未知面参考色先验，减少表面色块；仍为开发候选。',47:'用同一方向光先验处理食物与缺口；部分切面仍显平面化，未作为最终候选。',48:'食物和缺口联合细化；同噪声比较自由细化与粗结构约束，完整保留两类合成。',49:'与 G48 参数匹配的纯噪声对照；输入、遮罩、提示与随机种子保持一致。',50:'放大勺上食物与盘中缺口，共同生成材质；视图布局与分辨率同时改变，不能归因于单个因素。',51:'使用实际推断网格追踪缺口遮蔽；保留全部强度对照，遮蔽本身不能保证材质自然。',52:'正值源图颜色插值与有界生成微纹理；避免颜色外推，切面仍可能呈平面色块。',53:'受约束梯度积分与源图边界连续；属于图像外观先验，不是实测散射或材料模型。',54:'真实照片提供外观条件，动作布局单独编码为固定上下文；与 G50 同遮罩、同种子对照。',55:'在 G54 的真实外观条件上增加粗粒度动作约束；其空间和时间权重来自已保存的 G48 方案。',56:'共用几何、源图材质与种子，分开生成食物及缺口；同时改变上下文、约束与语义提示，属于组合设计对照。'}
    status_text={'complete_visually_reviewed':'已完成并全量审阅','running':'模型推理中','waiting_for_predecessor':'等待前一阶段完成','complete_unreviewed':'已生成，待全量审阅'}
    for name,g in review['gates'].items():
        if not re.fullmatch(r'v\d+',name) or int(name[1:])<35:continue
        text=brief.get(int(name[1:]),g.get('decision','详见原始审阅记录'));raw=g.get('new_raw_calls',g.get('neural_calls',g.get('new_neural_calls','—')));comps=g.get('compositions_reviewed','未记录')
        if g['status'] in ['running','waiting_for_predecessor']:
            stage=state.get('live_stages',{}).get('gate_'+name,{});raw=str(sum(w.get('completed',0) for w in stage.get('workers',[])))+'/'+str(g.get('expected_new_raw_calls','?'));comps='待审阅'
        rows.append('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in [name.upper(),status_text.get(g['status'],g['status']),raw,comps,text])+'</tr>')
    live=[]
    for name,s in state.get('live_stages',{}).items():
        workers=s.get('workers',[]);done=sum(w.get('completed',0) for w in workers);expected=sum(w.get('expected',0) for w in workers);live.append(f'<li>{html.escape(name)}：{html.escape(str(s.get("execution")))}；模型原始输出 {done}/{expected}。</li>')
    links=['ALL_CASE_ACCEPTANCE_20261001.json','CONTINUATION_REVIEW_20261001.json','EXECUTION_STATE_20261001.json','GEOMETRY_PROXY_AUDIT_SUMMARY_20261001.json','SAM3_DIAGNOSTICS_SUMMARY_20261001.json','ARCHIVE_TRANSFER_AUDIT_20261001.json','original_input_integrity_20261001.json','continuation_reproduction_code_inputs_20261001.zip']
    doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>真实图片第一口实验 · 实验记录</title><style>body{max-width:1120px;margin:40px auto;padding:0 24px;font:17px/1.75 system-ui;color:#172130;background:#f5f7fa}article{background:white;padding:28px;border-radius:16px}h1{font-size:30px}h2{font-size:23px;margin-top:30px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border-bottom:1px solid #dde3eb;text-align:left;vertical-align:top}a{color:#1257b5}.notice{padding:16px;background:#fff1d6;border-radius:10px}code{font-size:14px}img{max-width:100%}</style><article><h1>真实图片的入口前第一口实验</h1><p class="notice">持续开发版本。已运行和已审阅状态以保存的记录为准；尚未取得“完美”、独立真实性验收或新数据泛化结论。</p><p>目标是同一份食物的一小口由餐具托起，明显离开盘面，盘中出现对应缺口，同时保持原图的食物、配料和环境，不增加人物或手。</p><p><a href="gallery/index.html">打开全部案例、方法与随机种子的交互对照页</a></p><h2>输入与验证范围</h2><p>使用八张真实单图，保留原生分辨率照片、预处理图、近似标注和文件哈希。八张图均已经反复用于开发；历史文件名或 split 字段中的 prospective 不代表现在的独立测试集。没有同一食物真实移动前后配对照片、标定相机、扫描、测量材料参数或盲评。</p><h2>算法组成</h2><p>源图的可见轮廓和近似关键点决定单图食物形状及相机先验；共享切割体同时定义盘中缺口和被抬起的部分；餐具姿态同时受可见性与假定的静态支撑限制。被移动部分的可见继承表面，通过受切走区域约束的原图对应关系获取颜色。新切面、遮挡面、盘面延续和光照仍需要推断。</p><p>Qwen 是图像生成与材质外观先验；SAM3 是有误差的二维诊断观察器。自编程序负责共享切割、姿态、源图对应、局部约束、照明投影、合成及审计。本实验没有训练新的基础模型，也没有核实方法的新颖性。</p><h2>最新执行状态</h2><ul>'''+''.join(live)+'''</ul><h2>逐阶段记录</h2><table><thead><tr><th>阶段</th><th>状态</th><th>新增模型输出</th><th>审阅合成图</th><th>判断与范围</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><h2>可以确认什么</h2><p>原始输入文件已逐个核对。图像审计检查的是输入输出哈希、合成前保护区域、最终编辑区域之外的原图一致性、以及实际去噪过程的上下文约束。模型原始输出、受约束合成图和统计投影结果分开保存；最终合成的像素约束不能被当作原始模型行为。</p><p>G37 的闭合几何、共享切割分区、实际构造的餐具接触和静态力矩平衡，均只在单图推断的刚性、均匀密度几何及假定摩擦条件下成立。它们不能证明实际食物的尺度、变形或质量守恒。G48/G49/G50/G54/G55/G56 允许边界细化后，其生成结果的轮廓、接触与体积更不能直接继承 G37 几何审计结论。</p><h2>当前质量判断</h2><p>抬升、餐具托举、对应缺口、源图配料及材质自然度需要分别检查；任何一个通过不能代替整张图片通过。连续颜色置信度减少材质边界的色块；联合食物与缺口细化、放大双视图、几何遮蔽及梯度积分均保留全部结果；逐阶段审阅结论以记录为准。几何颜色投影有助于保持动作，但多个案例仍有生硬切面和刚性食物外观。真实外观条件与动作上下文分离的对照正在验证。多个随机种子的完整结果保留，不按单张最好结果替换默认种子。SAM3 检测到食物只说明二维检测，不是照片真实、接触正确或无手的证明。</p><p>前期下边缘斑点的实证原因是 CPU 食物标签与 GPU 颜色光栅边界混用，导致金属颜色进入食物；没有证据把这个错误归因于穿模或 z-fighting。</p><h2>结果与证据文件</h2><p>对照图固定显示种子 41，列为源图、旧方法和当前开发候选；全部种子见交互页。候选不是最终验收结论。</p><img src="gallery/all_cases_seed41.jpg" alt="八张真实源图和固定种子结果对照"><ul>'''+''.join('<li><a href="'+x+'">'+x+'</a></li>' for x in links)+'''</ul><p>报告刷新时间（Unix 秒）：'''+str(time.time())+'''。源代码、版本、参数、原始输出和文件哈希用于追溯这一次执行；模型权重未包含在复现压缩包内。该包记录本次服务器上的代码、输入和版本；脚本仍引用既有服务器目录和前序资产，尚不是可在新机器一键运行的完整移植包。</p></article></html>'''
    assert '\ufffd' not in doc;(r/'EXPERIMENT_REPORT_20261001.html').write_text(doc,encoding='utf-8');print('REPORT_REFRESHED',len(rows),flush=True)
if __name__=='__main__':main()
